import heapq

def shortest_path(edges, start, end):
    """
    Computes the shortest total distance and the corresponding path between two nodes
    in a directed graph represented by a list of edges. Each edge is a tuple
    (from_node, to_node, weight).

    Args:
        edges (list of tuples): Directed weighted edges as (from, to, weight)
        start (str/int): Starting node
        end (str/int): Ending node

    Returns:
        tuple: (distance, path) if a valid path exists
               (None, None) if no path exists from start to end

    Raises:
        ValueError: If any edge has a negative weight
    """
    # Handle same start and end node
    if start == end:
        return (0, [start])

    # Build adjacency list
    graph = {}
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight is not allowed")
        if from_node not in graph:
            graph[from_node] = {}
        if to_node not in graph[from_node]:
            graph[from_node][to_node] = 0
        graph[from_node][to_node] = min(graph[from_node].get(to_node, float('inf')), weight)

    # Initialize distances and predecessor tracking
    all_nodes = set()
    for u, neighbors in graph.items():
        all_nodes.add(u)
        all_nodes.update(neighbors.keys())

    distances = {node: float('inf') for node in all_nodes}
    predecessors = {}
    distances[start] = 0

    # Priority queue: (distance, node)
    pq = [(0, start)]
    visited = set()

    while pq:
        dist, u = heapq.heappop(pq)
        if u in visited:
            continue
        visited.add(u)

        if u == end:
            break

        for v, weight in graph.get(u, {}).items():
            new_dist = dist + weight
            if new_dist < distances[v]:
                distances[v] = new_dist
                predecessors[v] = u
                heapq.heappush(pq, (new_dist, v))

    # If end node was never reached
    if distances.get(end, float('inf')) == float('inf'):
        return (None, None)

    # Reconstruct path from end to start
    path = []
    current = end
    while current != start:
        path.append(current)
        current = predecessors[current]
    path.append(start)
    path.reverse()

    return (distances[end], path)
